import * as store from "../runtime/store.js";
import type { Row } from "../runtime/store.js";
import type { Slot, Client, Booking } from "../types.js";

// The step may touch only the tables it declares.
const all = (table: "Slot" | "Booking"): Row[] => store.all(table);
const find = (table: "Slot" | "Booking", id: string): Row | undefined => store.find(table, id);

export async function findOpenSlots(client: Client): Promise<Slot[]> {
  const now = Date.now();
  const bookedSlotIds = new Set(
    (all("Booking") as Booking[]).map((b) => b.slot_id)
  );
  return (all("Slot") as Slot[])
    .filter((s) => {
      const t = Date.parse(s.starts_at);
      return !Number.isNaN(t) && t >= now && !bookedSlotIds.has(s.id);
    })
    .sort((a, b) => Date.parse(a.starts_at) - Date.parse(b.starts_at));
}
